const BASE = 'http://localhost:5000';

function headers() {
  const token = localStorage.getItem('admin_token');
  return {
    'Content-Type': 'application/json',
    ...(token ? { Authorization: `Bearer ${token}` } : {}),
  };
}

async function req(method, path, body) {
  const res = await fetch(`${BASE}${path}`, {
    method,
    headers: headers(),
    ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.message || 'Request failed');
  return data;
}

// Auth
export const login = (email, password) =>
  req('POST', '/auth/login', { email, password });

// Products
export const getProducts = (params = {}) => {
  const q = new URLSearchParams(params).toString();
  return req('GET', `/products${q ? '?' + q : ''}`);
};
export const getProduct  = id  => req('GET', `/products/${id}`);
export const createProduct = d => req('POST', '/products', d);
export const updateProduct = (id, d) => req('PUT', `/products/${id}`, d);
export const deleteProduct = id => req('DELETE', `/products/${id}`);

export async function uploadProductFile(productId, file) {
  const fd = new FormData();
  fd.append('file', file);
  const token = localStorage.getItem('admin_token');
  const res = await fetch(`${BASE}/products/${productId}/upload`, {
    method: 'POST',
    headers: token ? { Authorization: `Bearer ${token}` } : {},
    body: fd,
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.message || 'Upload failed');
  return data;
}

// Categories
export const getCategories  = ()    => req('GET',  '/categories');
export const createCategory = d     => req('POST', '/categories', d);
export const updateCategory = (id,d)=> req('PUT',  `/categories/${id}`, d);
export const deleteCategory = id    => req('DELETE',`/categories/${id}`);

// Orders
export const getAllOrders    = ()        => req('GET', '/orders');
export const updateOrderStatus = (id,s) => req('PUT', `/orders/${id}/status`, { status: s });

// Stats helper — derived from orders list
export function computeStats(orders = [], products = []) {
  const revenue = orders.reduce((s, o) => s + Number(o.total_amount || 0), 0);
  const pending  = orders.filter(o => o.status === 'pending').length;
  return {
    revenue,
    orders:   orders.length,
    products: products.length,
    pending,
  };
}
